// Throwaway: re-run ONLY codegen + probe + render for an existing job's plan
// with a different model. Run from app/: npx tsx <this file> <jobId> <model>
import fs from 'node:fs/promises';
import path from 'node:path';
const APP = 'C:/Users/athar/Documents/Github/Shawtty/app';
const { config, paths } = await import(`file:///${APP}/server/config.ts`);
const { buildCustomVisual } = await import(`file:///${APP}/server/codegen.ts`);
const { probeEntry, renderReel } = await import(`file:///${APP}/server/render.ts`);
const { getAudioDuration } = await import(`file:///${APP}/server/media.ts`);

const [sourceId, model] = process.argv.slice(2);
if (!sourceId || !model) throw new Error('usage: <jobId> <model>');

const source = path.join(paths.reelDir, sourceId);
const plan = JSON.parse(await fs.readFile(path.join(source, 'plan.json'), 'utf8'));
const job = JSON.parse(await fs.readFile(path.join(source, 'job.json'), 'utf8'));
const jobId = `exp-${model.replace(/[^a-z0-9.]+/gi, '-')}-${sourceId.slice(-8)}`;
await fs.mkdir(path.join(paths.reelDir, jobId), { recursive: true });

config.videoModel = model;
const t0 = Date.now();
const entryPath = await buildCustomVisual({ jobId, plan });
console.log(`codegen ${entryPath ? 'ok' : 'FAILED'} in ${((Date.now() - t0) / 1000).toFixed(0)}s`);
if (!entryPath) {
  console.log(await fs.readFile(path.join(paths.reelDir, jobId, 'codegen.json'), 'utf8'));
  process.exit(1);
}

const audioName = `${sourceId}.mp3`;
const durationInSeconds = await getAudioDuration(path.join(APP, 'public', 'generated', audioName));
const inputProps = {
  jobId,
  title: plan.title,
  theme: plan.theme,
  prompt: job.prompt,
  narration: plan.narration,
  scenes: plan.scenes,
  style: plan.style,
  audioFile: `http://localhost:${config.port}/generated/${audioName}`,
  durationInSeconds,
  createdAt: job.createdAt,
  images: plan.images,
};
const { serveUrl } = await probeEntry({ jobId, entryPath, inputProps });
console.log('probe clean');
await renderReel({ jobId, inputProps, customEntry: entryPath, serveUrl });
console.log(`rendered reel/${jobId}/reel.mp4 in ${((Date.now() - t0) / 1000).toFixed(0)}s total`);

