// ONE paid codegen call (no retries, no repair rounds), then the app's real
// strip → scan → tsc → probe → render chain. Run from app/.
import fs from 'node:fs/promises';
import path from 'node:path';
const APP = 'C:/Users/athar/Documents/Github/Shawtty/app';
const { config, paths } = await import(`file:///${APP}/server/config.ts`);
const codegen = await import(`file:///${APP}/server/codegen.ts`);
const { probeEntry, renderReel } = await import(`file:///${APP}/server/render.ts`);
const { getAudioDuration } = await import(`file:///${APP}/server/media.ts`);

const MODEL = 'anthropic/claude-sonnet-5.5';
const SOURCE = '20261012063936-678fd664';
const jobId = `exp-sonnet-5.5-${SOURCE.slice(-8)}`;
const jobDir = path.join(paths.reelDir, jobId);
await fs.mkdir(jobDir, { recursive: true });

const plan = JSON.parse(await fs.readFile(path.join(paths.reelDir, SOURCE, 'plan.json'), 'utf8'));
const job = JSON.parse(await fs.readFile(path.join(paths.reelDir, SOURCE, 'job.json'), 'utf8'));

// Same brief buildCustomVisual builds (codegen.ts:342-365).
const brief = {
  title: plan.title,
  theme: plan.theme ?? 'education',
  mood: plan.style.mood,
  tokens: { bg: '#0B0D12', text: '#F2F4F8', muted: '#9AA3B2', accent: plan.style.palette[1] ?? '#7C83FF', accent2: plan.style.palette[2] ?? '#22D3EE' },
  beats: plan.scenes.map((s: any) => ({
    text: s.narrationBeat || s.body, start: typeof s.start === 'number' ? s.start : 0, end: typeof s.end === 'number' ? s.end : 0,
    visual: s.visual, headline: s.headline, hasPhoto: Boolean(s.imageUrl || s.visualData?.imageUrl), visualDataJson: JSON.stringify(s.visualData ?? {}),
  })),
};
const { system, user } = codegen.buildCodegenPrompt(brief);

const t0 = Date.now();
const res = await fetch(`${config.fallbackBaseUrl}/chat/completions`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${config.apiKey}` },
  body: JSON.stringify({ model: MODEL, temperature: 0.5, max_tokens: 16000, response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }] }),
});
const j = await res.json().catch(() => null);
const choice = j?.choices?.[0];
console.log({ status: res.status, secs: Math.round((Date.now() - t0) / 1000), finish: choice?.finish_reason,
  completionTokens: j?.usage?.completion_tokens, costInr: j?.usage?.cost });
const content: string = choice?.message?.content ?? '';
if (!content) { console.log('NO CONTENT — stopping.'); process.exit(1); }
await fs.writeFile(path.join(jobDir, 'raw-response.txt'), content);

let code = '';
try { code = String(JSON.parse(content).code ?? ''); }
catch { const m = content.match(/\{[\s\S]*\}/); code = m ? String(JSON.parse(m[0]).code ?? '') : ''; }
if (code.length < 200) { console.log('No usable code in response — see raw-response.txt'); process.exit(1); }

const surgery = codegen.stripFrozenMotion(code);
if (surgery.stripped.length) console.log('stripped:', surgery.stripped.join(', '));
code = surgery.code;
const scan = codegen.scanGeneratedCode(code);
console.log('scan:', scan);
await fs.writeFile(path.join(jobDir, codegen.GENERATED_VISUAL_FILE), `${code.replace(/\s+$/, '')}\n`);
await fs.writeFile(path.join(jobDir, codegen.GENERATED_ENTRY_FILE), `${codegen.buildEntrySource()}\n`);
console.log(`code: ${code.length} chars, svg: ${(code.match(/<svg/g) ?? []).length}, path: ${(code.match(/<path/g) ?? []).length}`);
if (!scan.ok) process.exit(1);
const typeError = await codegen.typecheckVisualCode(path.join(jobDir, codegen.GENERATED_VISUAL_FILE));
console.log('tsc:', typeError ?? 'clean');
if (typeError) process.exit(1);

const audioName = `${SOURCE}.mp3`;
const durationInSeconds = await getAudioDuration(path.join(APP, 'public', 'generated', audioName));
const inputProps = { jobId, title: plan.title, theme: plan.theme, prompt: job.prompt, narration: plan.narration, scenes: plan.scenes,
  style: plan.style, audioFile: `http://localhost:${config.port}/generated/${audioName}`, durationInSeconds, createdAt: job.createdAt, images: plan.images };
const entryPath = path.join(jobDir, codegen.GENERATED_ENTRY_FILE);
const { serveUrl } = await probeEntry({ jobId, entryPath, inputProps });
console.log('probe clean');
await renderReel({ jobId, inputProps, customEntry: entryPath, serveUrl });
console.log(`rendered reel/${jobId}/reel.mp4 (${Math.round((Date.now() - t0) / 1000)}s total)`);

